<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\AdmissionCampaign;use Illuminate\Http\Request;class AdmissionCampaignController extends Controller{public function index(){return view('admin.admission.index',['items'=>AdmissionCampaign::latest()->get()]);}public function create(){return view('admin.admission.form',['item'=>new AdmissionCampaign]);}public function store(Request $r){AdmissionCampaign::create($this->data($r));return redirect()->route('admin.admission-campaigns.index')->with('ok','Кампания создана');}public function edit(AdmissionCampaign $admission_campaign){return view('admin.admission.form',['item'=>$admission_campaign]);}public function update(Request $r,AdmissionCampaign $admission_campaign){$admission_campaign->update($this->data($r));return redirect()->route('admin.admission-campaigns.index')->with('ok','Сохранено');}public function destroy(AdmissionCampaign $admission_campaign){$admission_campaign->delete();return back();}private function data(Request $r){$d=$r->validate(['title'=>'required|max:255','status'=>'required|in:planned,open,closed,results','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at','announcement'=>'nullable|max:2000','content'=>'nullable']);$d['is_active']=$r->boolean('is_active');return $d;}}